  sunColor:     ['#ffcf8e', '#ff8f40', '#ff8a5a'],
  lightColor:   ['#ffc88a', '#ff9058', '#8f9fe8'],
  ambientColor: ['#a3b6e2', '#7e78b8', '#4c66b6'],
  groundLight:  ['#7a6652', '#66475a', '#262e50'],
  cloudLit:     ['#ffdcae', '#ff8c50', '#6076ae'],
  cloudShade:   ['#6f668e', '#3a2d58', '#1e2a52'],
