  const sunBear = mono([[0, 300], [F.T('south-south-east'), 337.5], [F.T('north-north-west'), 360], [DURATION, 360]]);
  const P = {}; for (const k in PALETTES) P[k] = typeof PALETTES[k][0] === 'string' ? PALETTES[k].map((c) => new THREE.Color(c)) : PALETTES[k];
  const state = { T: -1, high: 0, bearing: 0, sunDir: new THREE.Vector3(), keyDir: new THREE.Vector3(), lightDir: new THREE.Vector3(), fogColor: new THREE.Color() };
  for (const k in P) state[k] = typeof PALETTES[k][0] === 'string' ? new THREE.Color() : 0;
